  if(s.endsWith('-')){if(negative)return fail('invalid_amount');negative=true;s=s.slice(0,-1);}
  if(s.startsWith('-')){if(negative)return fail('invalid_amount');negative=true;s=s.slice(1);}else if(s.startsWith('+'))s=s.slice(1);
